  const A=norm(a),B=norm(b);if(!A||!B)return 0;if(A===B)return 100;if(A.includes(B)||B.includes(A))return 92;
  const aa=new Set(tokens(A)),bb=new Set(tokens(B));let hit=0;for(const t of aa)if(bb.has(t))hit++;
