  const html=await fetchText(`${TRACE_ORIGIN}/search/team/${id}`),candidate={id,name:htmlText((html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i)||[])[1])||fp.team_name},watches=parseWatchLinks(html);let best=null;
  for(const w of watches){const ev=gameEvidence(candidate,w,fp),score=ev.score+(nameScore(candidate.name,fp.team_name)>=60?3:0);if(!best||score>best.score)best={slug:w.team_slug,score,game:w.game_id};}
  if(!best?.slug){const counts=new Map();for(const w of watches)counts.set(w.team_slug,(counts.get(w.team_slug)||0)+1);const top=[...counts.entries()].sort((a,b)=>b[1]-a[1])[0];if(top)best={slug:top[0],score:5};}
